-- ============================================================================
-- ALL-IN-ONE SQL SETUP SCRIPT FOR MYSQL / SQL WORKBENCH (SOURCE CORE BANKING)
-- Run this script completely in MySQL Workbench to initialize and seed
-- all legacy source tables so that BDD ETL Automation passes 100%.
-- ============================================================================

CREATE DATABASE IF NOT EXISTS legacy_banking;
USE legacy_banking;

SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = '';

-- ============================================================================
-- ON-PREMISES LEGACY CORE BANKING SYSTEM (SQL DATABASE SCHEMA)
-- Dialect: Standard SQL (SQL Server / MySQL / PostgreSQL / SQLite Compatible)
-- Description: Operational Core Banking (OLTP) tables with legacy data formats,
--              abbreviated codes, raw PII, and mixed data quality issues.
-- ============================================================================

DROP TABLE IF EXISTS LEGACY_TRANSACTIONS;
DROP TABLE IF EXISTS LEGACY_LOANS;
DROP TABLE IF EXISTS LEGACY_ACCOUNTS;
DROP TABLE IF EXISTS LEGACY_CUSTOMERS;
DROP TABLE IF EXISTS LEGACY_BRANCHES;

-- 1. Legacy Branches Master
CREATE TABLE LEGACY_BRANCHES (
    BRANCH_ID           INT PRIMARY KEY,
    BRANCH_CODE         VARCHAR(10) NOT NULL UNIQUE,
    BRANCH_NAME         VARCHAR(100) NOT NULL,
    REGION              VARCHAR(50) NOT NULL,
    POSTAL_CODE         VARCHAR(20),
    CREATED_DATE        VARCHAR(20)
);

-- 2. Legacy Customer Master (Contains unmasked PII, unstandardized names, legacy status codes)
CREATE TABLE LEGACY_CUSTOMERS (
    CUST_ID             INT PRIMARY KEY,
    FULL_NAME           VARCHAR(120) NOT NULL,
    TAX_ID_SSN          VARCHAR(20) NOT NULL,       -- Raw PII: e.g. 123-45-6789 or 987654321012
    EMAIL               VARCHAR(100),               -- Dirty formats present in legacy
    PHONE_NO            VARCHAR(30),                -- Raw unformatted phone
    CUST_STATUS         CHAR(1) NOT NULL,           -- 'A'=Active, 'I'=Inactive, 'D'=Deceased, 'S'=Suspended
    KYC_FLAG            INT NOT NULL DEFAULT 0,     -- 1=Completed, 0=Pending
    CREDIT_SCORE        INT,
    DOB_INT             INT,                        -- Legacy integer format: YYYYMMDD (e.g. 19850624)
    CITY                VARCHAR(50),
    STATE_PROV          VARCHAR(50),
    CREATED_TIMESTAMP   VARCHAR(30)
);

-- 3. Legacy Accounts Master
CREATE TABLE LEGACY_ACCOUNTS (
    ACCT_NO             VARCHAR(20) PRIMARY KEY,
    CUST_ID             INT NOT NULL,
    BRANCH_CODE         VARCHAR(10) NOT NULL,
    ACCT_TYPE           VARCHAR(10) NOT NULL,       -- 'SAV', 'CHK', 'MMA', 'LON', 'CD'
    CURRENT_BAL         DECIMAL(18, 2) NOT NULL,
    INTEREST_RATE       DECIMAL(5, 2) NOT NULL,
    ACCT_STATUS         CHAR(1) NOT NULL,           -- 'O'=Open, 'C'=Closed, 'D'=Dormant
    OPEN_DATE_STR       VARCHAR(20) NOT NULL,       -- e.g. '2018-04-12' or '12/04/2018'
    OVERDRAFT_LIMIT     DECIMAL(18, 2) DEFAULT 0.00,
    FOREIGN KEY (CUST_ID) REFERENCES LEGACY_CUSTOMERS(CUST_ID),
    FOREIGN KEY (BRANCH_CODE) REFERENCES LEGACY_BRANCHES(BRANCH_CODE)
);

-- 4. Legacy Daily Financial Transactions
CREATE TABLE LEGACY_TRANSACTIONS (
    TXN_ID              VARCHAR(30) PRIMARY KEY,
    ACCT_NO             VARCHAR(20) NOT NULL,
    TXN_TIMESTAMP       VARCHAR(30) NOT NULL,       -- e.g. '2024-03-01 10:15:32'
    TXN_TYPE            CHAR(2) NOT NULL,           -- 'DR'=Debit, 'CR'=Credit
    TXN_CHANNEL         VARCHAR(10) NOT NULL,       -- 'ATM', 'NET', 'UPI', 'POS', 'BRN'
    AMOUNT              DECIMAL(18, 2) NOT NULL,
    RUNNING_BALANCE     DECIMAL(18, 2) NOT NULL,
    TXN_DESCRIPTION     VARCHAR(200),
    STATUS_CODE         VARCHAR(10) DEFAULT 'SUCCESS', -- 'SUCCESS', 'FAILED', 'PENDING'
    FOREIGN KEY (ACCT_NO) REFERENCES LEGACY_ACCOUNTS(ACCT_NO)
);

-- 5. Legacy Loan Portfolio
CREATE TABLE LEGACY_LOANS (
    LOAN_ID             VARCHAR(20) PRIMARY KEY,
    ACCT_NO             VARCHAR(20) NOT NULL,
    CUST_ID             INT NOT NULL,
    LOAN_TYPE           VARCHAR(20) NOT NULL,       -- 'HOME', 'AUTO', 'PERSONAL', 'EDUCATION'
    PRINCIPAL_AMT       DECIMAL(18, 2) NOT NULL,
    OUTSTANDING_AMT     DECIMAL(18, 2) NOT NULL,
    INTEREST_RATE       DECIMAL(5, 2) NOT NULL,
    EMI_AMT             DECIMAL(18, 2) NOT NULL,
    TERM_MONTHS         INT NOT NULL,
    DISBURSED_DATE_STR  VARCHAR(20) NOT NULL,
    DELINQUENCY_BUCKET  VARCHAR(10) NOT NULL,       -- '00'=Current, '30'=30 DPD, '60'=60 DPD, '90'=90+ DPD
    FOREIGN KEY (ACCT_NO) REFERENCES LEGACY_ACCOUNTS(ACCT_NO),
    FOREIGN KEY (CUST_ID) REFERENCES LEGACY_CUSTOMERS(CUST_ID)
);

-- Create indexes for operational lookup
CREATE INDEX IDX_LEGACY_CUST_STATUS ON LEGACY_CUSTOMERS(CUST_STATUS);
CREATE INDEX IDX_LEGACY_ACCT_CUST ON LEGACY_ACCOUNTS(CUST_ID);
CREATE INDEX IDX_LEGACY_TXN_ACCT ON LEGACY_TRANSACTIONS(ACCT_NO);
CREATE INDEX IDX_LEGACY_LOAN_ACCT ON LEGACY_LOANS(ACCT_NO);


-- ========================================================
-- DIRECT SEED DATA FOR MYSQL (LEGACY CORE BANKING)
-- Generated to bypass MySQL Workbench Import Wizard bugs
-- ========================================================

USE legacy_banking;

-- Disable Foreign Key checks temporarily during seed load
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = '';

