-- --------------------------------------------------------
DELETE FROM LEGACY_BRANCHES;

-- --------------------------------------------------------
-- 2. LEGACY_CUSTOMERS (160 rows)
-- --------------------------------------------------------
DELETE FROM LEGACY_CUSTOMERS;

-- --------------------------------------------------------
-- 3. LEGACY_ACCOUNTS (240 rows)
-- --------------------------------------------------------
DELETE FROM LEGACY_ACCOUNTS;

-- --------------------------------------------------------
-- 4. LEGACY_TRANSACTIONS (1500 rows)
-- --------------------------------------------------------
DELETE FROM LEGACY_TRANSACTIONS;

-- --------------------------------------------------------
-- 5. LEGACY_LOANS (75 rows)
-- --------------------------------------------------------
DELETE FROM LEGACY_LOANS;

-- Re-enable Foreign Key checks
SET FOREIGN_KEY_CHECKS = 1;

-- Verification Query:
SELECT 'LEGACY_BRANCHES' AS table_name, COUNT(*) AS row_cnt FROM LEGACY_BRANCHES
UNION ALL
SELECT 'LEGACY_CUSTOMERS', COUNT(*) FROM LEGACY_CUSTOMERS
UNION ALL
SELECT 'LEGACY_ACCOUNTS', COUNT(*) FROM LEGACY_ACCOUNTS
UNION ALL
SELECT 'LEGACY_TRANSACTIONS', COUNT(*) FROM LEGACY_TRANSACTIONS
UNION ALL
SELECT 'LEGACY_LOANS', COUNT(*) FROM LEGACY_LOANS;


SET FOREIGN_KEY_CHECKS = 1;
